require_once __DIR__.'/../includes/database.php';require_once __DIR__.'/../includes/list-sharing.php';require_once __DIR__.'/../includes/email-verification.php';require_once __DIR__.'/../includes/password-email.php';
function expect13(bool $test,string $message): void {if(!$test)throw new RuntimeException($message);}
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);initialize_database($db);
$db->exec("INSERT INTO users(name,public_name,email,password_hash) VALUES('Keep','Keep','keep@example.invalid','unused')");
$db->exec('DROP TABLE scan_list_shares');$db->exec('DELETE FROM app_schema_migrations WHERE version=30');initialize_database($db);initialize_database($db);expect13((int)$db->query('SELECT COUNT(*) FROM users')->fetchColumn()===1,'upgrade retains accounts');
$code=scan_list_share($db,['96385074'],fn()=>'AbCd1234');expect13($code==='AbCd1234','8-character alias');expect13(scan_list_share($db,['96385074'])===$code,'same payload deduplication');$tries=0;$second=scan_list_share($db,['4006381333931'],function()use(&$tries){return ++$tries===1?'AbCd1234':'AbCd5678';});expect13($second==='AbCd5678'&&$tries===2,'collision retry');
$ordered=['4006381333931','96385074'];$third=scan_list_share($db,$ordered);$q=$db->prepare('SELECT payload FROM scan_list_shares WHERE code=?');$q->execute([$third]);expect13(json_decode($q->fetchColumn(),true)===$ordered,'EAN order unchanged');
foreach([[],['invalid'],['00000001'],array_fill(0,201,'96385074')] as $invalid){try{scan_list_share($db,$invalid);throw new RuntimeException('invalid accepted');}catch(CatalogException $e){expect13($e->status===422,'validation');}}
foreach([welcome_email('Name <safe>','https://example.invalid/verify')['html'],reset_email_html('https://example.invalid/reset'),account_security_email_html('https://example.invalid')] as $html){expect13(str_contains($html,'#27197F')&&!str_contains($html,'#27187e'),'official brand');expect13(str_contains($html,'https://repotools.online/img/email/logo.png'),'public HTTPS logo');expect13(!str_contains($html,'<script'),'email compatible');preg_match_all('~src="https://repotools.online/([^"]+)"~',$html,$images);foreach($images[1] as $image)expect13(is_file(__DIR__.'/../'.$image),'local image exists');}
echo "OK: additive migration30, preserved accounts, alias collision/deduplication/order/validation, shared mail layout/colors/public images.\n";
